      "title": "The Uttermost Rim of River Oceanus Sealing the Cosmos",
      "greek": "Ἐν δ᾽ ἐτίθει ποταμοῖο μέγα σθένος Ὠκεανοῖο ἄντυγα πὰρ πυμάτην σάκεος πύκα ποιητοῖο.",
